// The methos must be implemented accross all child class of TAMRebateJournalTrans to set the aggregated string on rebate trans based on the aggregation type.
// For example, TAMRebateJournalTransSalesInvoice it should set salesInvoiceTable.CustAccount when _aggregatedBy is 'CustAccount'
public void inititalizeRebateTransactionFromJournal(TAMRebateTrans _rebateTrans)
{
    next inititalizeRebateTransactionFromJournal(_rebateTrans);

    // Set the aggregated string on the rebate trans.
    if (rebateTable.TAMRebateDeal().METAggregatedBy == METConstants::aggregateByCustomer)
    {
        _rebateTrans.METAggregatedStr = invoiceJour.InvoiceAccount == '' ? invoicejour.OrderAccount : invoiceJour.InvoiceAccount;
    }
}

/// <summary>
/// Sets the journal value to a local buffer as the main buffer and method are internal
/// </summary>
/// <param name = "_journal">Journal table record buffer</param>
/// <param name = "_transaction">Journal transaction record buffer</param>
public void setJournalTransaction(Common _journal, Common _transaction)
{
    next setJournalTransaction(_journal, _transaction);

    invoiceJour = _journal as custInvoiceJour;
}
